CREATE OR REPLACE FUNCTION public.evaluation_extended_acceptance_test() RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$ DECLARE uid text:='TEST-'||gen_random_uuid(); actor text:='TEST-'||gen_random_uuid(); reviewer text:='TEST-'||gen_random_uuid(); aid uuid:=gen_random_uuid(); bid uuid:=gen_random_uuid(); tpl uuid:=gen_random_uuid(); tx uuid; blocked boolean; v numeric; BEGIN BEGIN INSERT INTO public."Users"("ID","Role","Status","Team_ID") VALUES(uid,'Member','Active','test-team'); INSERT INTO public."Evaluation_Permissions"(user_id,screen,team_id,actions,granted_by) VALUES(actor,'church','test-team','raed','MASTER-ADMIN'),(reviewer,'points_approval','test-team','re','MASTER-ADMIN'); IF NOT public.evaluation_can(actor,'church','e','test-team') OR public.evaluation_can(actor,'church','e','other-team') THEN RAISE EXCEPTION 'Team boundary failed'; END IF; INSERT INTO public."Evaluation_Activities"(id,module,title,audience,team_ids,starts_at,ends_at,state,created_by,attendance_points) VALUES(aid,'church','Acceptance rejection','Member',ARRAY['test-team'],now()-interval '1 hour',now()+interval '1 hour','Published',actor,10); PERFORM public.evaluation_submit(aid,actor,jsonb_build_array(jsonb_build_object('user_id',uid,'attendance_status','Present'))); SELECT id INTO tx FROM public."Points_Transactions" WHERE activity_id=aid; blocked:=false; BEGIN PERFORM public.review_points_transaction(tx,reviewer,false,''); EXCEPTION WHEN OTHERS THEN blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'Empty rejection accepted'; END IF; PERFORM public.review_points_transaction(tx,reviewer,false,'Rejected test'); SELECT coalesce(sum(amount),0) INTO v FROM public."Points_Transactions" WHERE user_id=uid AND status='Approved'; IF v<>0 THEN RAISE EXCEPTION 'Rejected points counted'; END IF; INSERT INTO public."Evaluation_Templates"(id,module,title,team_ids,recurrence,created_by) VALUES(tpl,'notebook','Weekly acceptance',ARRAY['test-team'],'weekly','MASTER-ADMIN'); INSERT INTO public."Evaluation_Activities"(id,module,title,audience,team_ids,starts_at,ends_at,state,created_by,template_id) VALUES(bid,'notebook','Template test','Member',ARRAY['test-team'],now()-interval '1 hour',now()+interval '1 hour','Draft','MASTER-ADMIN',tpl); INSERT INTO public."Evaluation_Criteria"(activity_id,title,points) VALUES(bid,'Criterion',10); UPDATE public."Evaluation_Activities" SET state='Published' WHERE id=bid; PERFORM public.evaluation_submit(bid,'MASTER-ADMIN',jsonb_build_array(jsonb_build_object('user_id',uid,'answers','{}'::jsonb))); aid:=gen_random_uuid(); INSERT INTO public."Evaluation_Activities"(id,module,title,audience,team_ids,starts_at,ends_at,state,created_by,template_id) VALUES(aid,'notebook','Repeat template test','Member',ARRAY['test-team'],now()-interval '1 hour',now()+interval '1 hour','Published','MASTER-ADMIN',tpl); blocked:=false; BEGIN PERFORM public.evaluation_submit(aid,'MASTER-ADMIN',jsonb_build_array(jsonb_build_object('user_id',uid,'answers','{}'::jsonb))); EXCEPTION WHEN OTHERS THEN blocked:=true; END; IF NOT blocked THEN RAISE EXCEPTION 'Repeated weekly evaluation allowed'; END IF; aid:=gen_random_uuid(); INSERT INTO public."Evaluation_Activities"(id,module,title,audience,team_ids,starts_at,ends_at,state,created_by) VALUES(aid,'church','Scoped deletion','Member',ARRAY['test-team'],now(),now()+interval '1 hour','Draft',actor); PERFORM public.evaluation_delete_draft(aid,actor); IF EXISTS(SELECT 1 FROM public."Evaluation_Activities" WHERE id=aid) THEN RAISE EXCEPTION 'Scoped deletion failed'; END IF; RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='EXTENDED_ACCEPTANCE_ROLLBACK'; EXCEPTION WHEN NO_DATA_FOUND THEN IF SQLERRM<>'EXTENDED_ACCEPTANCE_ROLLBACK' THEN RAISE; END IF; END; RETURN jsonb_build_object('team_boundary',true,'rejection_reason',true,'rejected_official',0,'weekly_repeat_denied',true,'scoped_draft_delete',true,'rolled_back',true); END $$;
REVOKE ALL ON FUNCTION public.evaluation_extended_acceptance_test() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.evaluation_extended_acceptance_test() TO service_role;